{"t":"step","id":"translate","kind":"ai","label":"Translate rule","task":"translate","ai":"qwen3.8-flash","runs":"fc","repeat":"per-rule","why":"Convert non-English regulations into the corporate language"}
{"t":"step","id":"retrieve-policies","kind":"knowledge","label":"Retrieve related policies","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","repeat":"per-rule","private":true,"why":"Find internal policies that may be affected by the new rule"}
{"t":"step","id":"rank-policies","kind":"knowledge","label":"Rank policy matches","task":"rerank","ai":"qwen3-rerank","runs":"fc","repeat":"per-rule","after":"retrieve-policies","why":"Re-score retrieved policies for relevance to the translated rule"}
