{"t":"step","id":"deliver","kind":"act","label":"Deliver approved memo","effect":"send","runs":"agentcore","repeat":"per-rule","why":"Send approved memo to the compliance management system or inbox"}
{"t":"step","id":"end-approved","kind":"end","label":"Memo delivered","runs":"customer","repeat":"per-rule"}
{"t":"step","id":"end-rejected","kind":"end","label":"Memo rejected","runs":"customer","repeat":"per-rule"}
{"t":"step","id":"done-all","kind":"end","label":"Daily run complete","runs":"customer","after":"per-rule","why":"Wait for all parallel rule items to finish before ending the run"}
