{"t":"say","text":"Orchestrator with workers pattern: parse, retrieve policy, draft, hallucination check, and SME approval routing."}
{"t":"assume","id":"rfp-format","text":"RFPs arrive as PDF or Word attachments via email or upload","alt":"RFPs are pasted as plain text in a chat channel"}
{"t":"assume","id":"policy-store","text":"Approved policies are stored in a vector database for RAG","alt":"Policies live in OSS files parsed on demand"}
{"t":"assume","id":"sme-routing","text":"SME assignment is based on topic classification of each question","alt":"All SMEs review every drafted answer together"}
{"t":"ask","id":"volume","text":"How many RFP documents do you expect to process per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline turnaround time?"}
{"t":"step","id":"in","kind":"trigger","label":"Receive RFP document","product":"eventbridge","runs":"fc","untrusted":true,"why":"Entry point for incoming RFP files or messages"}
{"t":"step","id":"guard-in","kind":"guard","label":"Screen inbound RFP","product":"ai-guardrails","runs":"fc","why":"Block prompt injection or harmful content in uploads"}
{"t":"step","id":"parse-rfp","kind":"agent","label":"Parse RFP questions","task":"extract","ai":"qwen3.7-plus","tool":"pdf_parse","turns":10,"runs":"agentrun","untrusted":true,"why":"Extract structured questions and requirements from the RFP"}
{"t":"each","id":"per-question","over":"parsed RFP questions","parallel":true}
{"t":"step","id":"classify-topic","kind":"ai","label":"Classify question topic","task":"classify","ai":"qwen3.8-flash","runs":"fc","repeat":"per-question","why":"Determine which SME team should review this answer"}
{"t":"step","id":"retrieve-policy","kind":"knowledge","label":"Retrieve approved policy","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","repeat":"per-question","why":"Fetch relevant approved policy snippets for grounding"}
{"t":"step","id":"rank-policy","kind":"knowledge","label":"Rank policy evidence","task":"rerank","ai":"qwen3-rerank","runs":"fc","repeat":"per-question","why":"Ensure only the most relevant policy text is used"}
{"t":"step","id":"draft-answer","kind":"ai","label":"Draft RFP answer","task":"generate","ai":"qwen3.7-plus","runs":"fc","repeat":"per-question","why":"Generate a grounded response using retrieved policy context"}
{"t":"step","id":"check-hallucination","kind":"ai","label":"Hallucination check","task":"check","ai":"qwen3.8-max","runs":"fc","repeat":"per-question","why":"Verify the draft is fully supported by retrieved policy evidence"}
{"t":"step","id":"decide-hallucination","kind":"decide","label":"Route by faithfulness","task":"decide","runs":"fc","repeat":"per-question","why":"Branch based on whether the answer passed hallucination check"}
{"t":"step","id":"redraft","kind":"ai","label":"Redraft with constraints","task":"generate","ai":"qwen3.7-plus","runs":"fc","repeat":"per-question","why":"Regenerate answer with stricter grounding instructions"}
{"t":"step","id":"route-sme","kind":"human","label":"SME sign-off","task":"approve","subject":"draft-answer","runs":"cloudflow","repeat":"per-question","why":"Subject matter expert reviews and approves the final answer"}
{"t":"step","id":"compile","kind":"ai","label":"Compile final RFP","task":"generate","ai":"qwen3.7-plus","runs":"fc","join":"all","why":"Assemble all approved answers into a single response document"}
{"t":"step","id":"deliver","kind":"act","label":"Deliver RFP response","effect":"send","product":"direct-mail","runs":"fc","approval":"required","why":"Send the compiled and approved RFP response to the requester"}
{"t":"step","id":"done-end","kind":"end","label":"RFP completed","runs":"customer","why":"Terminal state after successful delivery"}
{"t":"step","id":"fail-end","kind":"end","label":"RFP failed","runs":"customer","why":"Terminal state when hallucination check exhausts retries"}
{"t":"link","id":"l-in-guard","from":"in","to":"guard-in","kind":"next"}
{"t":"link","id":"l-guard-parse","from":"guard-in","to":"parse-rfp","kind":"next"}
{"t":"link","id":"l-parse-classify","from":"parse-rfp","to":"classify-topic","kind":"next"}
{"t":"link","id":"l-classify-retrieve","from":"classify-topic","to":"retrieve-policy","kind":"next"}
{"t":"link","id":"l-retrieve-rank","from":"retrieve-policy","to":"rank-policy","kind":"next"}
{"t":"link","id":"l-rank-draft","from":"rank-policy","to":"draft-answer","kind":"next"}
{"t":"link","id":"l-draft-check","from":"draft-answer","to":"check-hallucination","kind":"next"}
{"t":"link","id":"l-check-decide","from":"check-hallucination","to":"decide-hallucination","kind":"next"}
{"t":"link","id":"l-decide-pass","from":"decide-hallucination","to":"route-sme","kind":"branch","label":"faithful"}
{"t":"link","id":"l-decide-fail","from":"decide-hallucination","to":"redraft","kind":"branch","label":"hallucinated"}
{"t":"link","id":"l-redraft-loop","from":"redraft","to":"check-hallucination","kind":"loop","max":3}
{"t":"link","id":"l-redraft-exhaust","from":"redraft","to":"fail-end","kind":"branch","label":"exhausted"}
{"t":"link","id":"l-sme-approve","from":"route-sme","to":"compile","kind":"branch","outcome":"approve"}
{"t":"link","id":"l-sme-edit","from":"route-sme","to":"draft-answer","kind":"branch","outcome":"edit"}
{"t":"link","id":"l-sme-reject","from":"route-sme","to":"fail-end","kind":"branch","outcome":"reject"}
{"t":"link","id":"l-compile-deliver","from":"compile","to":"deliver","kind":"next"}
{"t":"link","id":"l-deliver-done","from":"deliver","to":"done-end","kind":"next"}
{"t":"done","summary":"Designed an orchestrator-with-workers agent that parses RFPs, retrieves policy, drafts and checks answers per question, loops on hallucinations up to 3 times, routes to SMEs for approval, then compiles and delivers."}

