{"t":"step","id":"retrieve","kind":"knowledge","label":"Retrieve help articles","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","after":"classify","why":"Find relevant knowledge base documents for grounded replies"}
